import java.util.*;

class Solution {
    private boolean dfs(int u, int[][] grid, int[] match, boolean[] seen, int n) {
        for (int v = 0; v < n; ++v) {
            if (grid[u][v] == 1 && !seen[v]) {
                seen[v] = true;
                if (match[v] == -1 || dfs(match[v], grid, match, seen, n)) {
                    match[v] = u;
                    return true;
                }
            }
        }
        return false;
    }

    public int maximumInvitations(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[] match = new int[n];
        Arrays.fill(match, -1);
        int ans = 0;
        for (int i = 0; i < m; ++i) {
            boolean[] seen = new boolean[n];
            if (dfs(i, grid, match, seen, n)) {
                ans++;
            }
        }
        return ans;
    }
}

