var maximumInvitations = function(grid) {
    const m = grid.length, n = grid[0].length;
    const match = Array(n).fill(-1);

    function dfs(u, seen) {
        for (let v = 0; v < n; ++v) {
            if (grid[u][v] === 1 && !seen[v]) {
                seen[v] = true;
                if (match[v] === -1 || dfs(match[v], seen)) {
                    match[v] = u;
                    return true;
                }
            }
        }
        return false;
    }

    let ans = 0;
    for (let i = 0; i < m; ++i) {
        const seen = Array(n).fill(false);
        if (dfs(i, seen)) {
            ans++;
        }
    }
    return ans;
};
